class Ledger:
    def __init__(self):
        self.entries = []
        self._seen = set()

    def apply_charge(self, event_id, amount):
        if event_id in self._seen:
            return
        self._seen.add(event_id)
        self.entries.append((event_id, amount))

    @property
    def total(self):
        return sum(amount for _, amount in self.entries)

