def clamp_window(start: int, end: int, limit: int):
    if start < 0 or end < 0:
        raise ValueError("negative boundary")
    if start > end:
        raise ValueError("reversed window")
    if start > limit:
        raise ValueError("window starts outside limit")
    return min(start, limit), min(end, limit)

